commands.command:
rpm -q policycoreutils-python-utils setools-console 2>&1
cat > /tmp/galera_sst.te <<'EOF'
module galera_sst 1.0;

require {
	type mysqld_t;
	class unix_stream_socket connectto;
}

#============= mysqld_t ==============
allow mysqld_t self:unix_stream_socket connectto;
EOF
cd /tmp && checkmodule -M -m -o galera_sst.mod galera_sst.te && semodule_package -o galera_sst.pp -m galera_sst.mod && semodule -i galera_sst.pp
semodule -l | grep galera_sst

systemctl enable mariadb 2>&1
mysql -e "
CREATE DATABASE IF NOT EXISTS appdb;
CREATE TABLE IF NOT EXISTS appdb.orders (
  id INT PRIMARY KEY AUTO_INCREMENT,
  item VARCHAR(100),
  created_from VARCHAR(20),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;
INSERT INTO appdb.orders (item, created_from) VALUES ('widget-A','node1'),('widget-B','node1'),('widget-C','node1');
"
mysql -e "CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY [REDACTED] GRANT ALL PRIVILEGES ON appdb.* TO 'appuser'@'%'; FLUSH PRIVILEGES;"
mysql -e "SELECT * FROM appdb.orders;"
